"""Generate the website article from recorded results and reviewed conclusions."""
import hashlib
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main():
    data = json.loads((ROOT / 'web/results.json').read_text())
    editorial = json.loads((ROOT / 'data/editorial.json').read_text())
    e = html.escape
    fast = data['totals']['fast']
    rows = ''.join(f'<tr><th scope="row">{e(g["title"])}<br><span class="brilly-small">{g["year"]}</span></th><td class="num">{g["stats"]["fast"]["targets"]}</td><td class="num" data-game-old="{g["id"]}">{g["stats"]["fast"]["oldHits"]}/{g["stats"]["fast"]["targets"]}</td><td class="num" data-game-new="{g["id"]}">{g["stats"]["fast"]["newHits"]}/{g["stats"]["fast"]["targets"]}</td></tr>' for g in data['games'])
    mode_rows = ''.join(f'<tr><th scope="row">{q.title()}</th><td class="num">{t["oldHits"]}/14</td><td class="num">{t["newHits"]}/14</td><td class="num">{t["oldAwards"]}</td><td class="num">{t["newAwards"]}</td></tr>' for q, t in data['totals'].items())
    sections = []
    for g in data['games']:
        cases = []
        for c in g['cases']:
            if not c['landmark']:
                continue
            m = c['modes']['fast']
            grade = lambda label: data['grades'][label or 'null']
            cases.append(f'<figure class="brilly-static-case"><h4>{e(c["move"])} — published !!</h4><p>{e(c["idea"])}</p><img loading="lazy" src="figures/{g["id"]}-{c["ply"]:03d}.png" width="960" height="550" alt="Actual board positions before and after {e(c["move"])} in {e(g["title"])}."><figcaption>Fast: {e(grade(m["old"]))} → {e(grade(m["new"]))}. {e(m["reason"])}</figcaption></figure>')
        sections.append(f'<details class="brilly-static-game"><summary>{e(g["title"])} · {g["year"]}</summary><p><a href="{e(g["source"]["url"], quote=True)}">Chosen published annotation</a></p>{"".join(cases)}</details>')
    source_links = ''.join(f'<li><a href="{e(g["source"]["url"], quote=True)}">{e(g["title"])}: {e(g["source"]["title"])}</a></li>' for g in data['games'])
    notes = ''.join(f'<li><strong>{e(n["title"])}</strong> {e(n["text"])}</li>' for n in editorial['notes'])
    body = f'''<main id="main" class="container research-page brilly-page">
<p class="breadcrumb"><a href="../">Research</a><span aria-hidden="true"> / </span>Brilliant moves</p>
<header class="brilly-hero"><div><p class="eyebrow">OPEN BRILLY FINDER · FAMOUS-GAME FIELD TRIP</p><h1>Can a model spot<br><em>a masterpiece?</em></h1><p>Nine famous games. Fourteen published <strong>!!</strong> landmarks. We gave our old and proposed Brilliant finders the same Stockfish analysis and compared their answers.</p><p class="brilly-target">Aiming for Mobile Maia 2.7 · Research, not a released feature</p><p><a class="button" href="#explore">Explore the positions</a></p></div><figure><img src="figures/hero-opera.png" width="1280" height="720" fetchpriority="high" alt="Morphy’s actual position before 16.Qb8+, offering the queen to deflect the knight from the mating square."><figcaption>The Opera Game, Paris 1858. A queen offer, then a rook’s final bow.</figcaption></figure></header>
<section class="brilly-section" aria-labelledby="verdict-title"><p class="eyebrow">THE RESULT</p><h2 id="verdict-title">{e(editorial['headline'])}</h2><p class="brilly-deck">{e(editorial['summary'])}</p><div class="brilly-note"><p>{e(editorial['releaseNote'])}</p></div></section>
<section class="brilly-section" aria-labelledby="score-title"><h2 id="score-title">Same games. Different spotlights.</h2><p>We fixed the games and chosen annotations before the new runs. The score below counts the fourteen published <strong>!!</strong> landmarks, not every move either app labels Brilliant.</p><div class="brilly-mode" role="group" aria-label="Analysis mode"><span>Analysis mode</span><button type="button" class="brilly-button" data-quality="fast" aria-pressed="true">Fast</button><button type="button" class="brilly-button" data-quality="balanced" aria-pressed="false">Balanced</button><button type="button" class="brilly-button" data-quality="thorough" aria-pressed="false">Thorough</button></div><p class="brilly-results" id="brilly-tally" aria-live="polite">{fast['oldHits']} → {fast['newHits']} of 14 published landmarks found</p><div class="brilly-table-wrap"><table class="brilly-table"><caption>Final app awards after the normal confirmation checks. Fast is the prespecified primary comparison.</caption><thead><tr><th>Game</th><th class="num">Landmarks</th><th class="num">Previous</th><th class="num">Open Brilly</th></tr></thead><tbody>{rows}</tbody></table></div><p class="brilly-small" id="brilly-total-awards">Total Brilliant awards across the nine games: previous {fast['oldAwards']}; Open Brilly Finder {fast['newAwards']}.</p><details class="brilly-mode-sensitivity"><summary>All modes and total awards</summary><div class="brilly-table-wrap"><table class="brilly-table"><thead><tr><th>Mode</th><th class="num">Previous landmarks</th><th class="num">New landmarks</th><th class="num">Previous total !!</th><th class="num">New total !!</th></tr></thead><tbody>{mode_rows}</tbody></table></div><p>More awards do not automatically mean better judgments. A missing published mark is not a negative label. The full move lists below include retained, gained and lost awards.</p></details></section>
<section class="brilly-section" id="explore" aria-labelledby="explore-title"><p class="eyebrow">TAKE A SEAT AT THE BOARD</p><h2 id="explore-title">Look at the move. Then the label.</h2><p>Choose a game and position. Switch between the board before and after the move, and compare the old grade, new grade and published annotation.</p><p id="brilly-load-status" class="brilly-small" role="status">Loading the recorded positions…</p><div class="brilly-explorer" id="brilly-explorer" hidden><div class="brilly-inputs"><label class="brilly-field">Game<select id="brilly-game"></select></label><label class="brilly-field">Position<select id="brilly-position"></select></label></div><div class="brilly-board-layout"><div class="brilly-board-panel"><div class="brilly-board-wrap"><div class="brilly-ranks" aria-hidden="true"><span>8</span><span>7</span><span>6</span><span>5</span><span>4</span><span>3</span><span>2</span><span>1</span></div><div id="brilly-board" class="brilly-board" role="img" aria-label="Recorded chess position"></div><div class="brilly-files" aria-hidden="true"><span>a</span><span>b</span><span>c</span><span>d</span><span>e</span><span>f</span><span>g</span><span>h</span></div></div><div class="brilly-board-actions" role="group" aria-label="Board position"><button type="button" class="brilly-button" id="brilly-before" aria-pressed="true">Before move</button><button type="button" class="brilly-button" id="brilly-after" aria-pressed="false">After move</button></div><div class="brilly-case-nav"><button type="button" class="brilly-button" id="brilly-previous">Previous position</button><span id="brilly-case-count" class="brilly-small"></span><button type="button" class="brilly-button" id="brilly-next">Next position</button></div></div><div class="brilly-case" aria-live="polite"><p class="brilly-small" id="brilly-game-title"></p><h3 id="brilly-case-title"></h3><p class="brilly-annotation" id="brilly-annotation"></p><p id="brilly-idea"></p><div class="brilly-grades"><div class="brilly-grade"><span>Previous classifier</span><strong id="brilly-old"></strong></div><div class="brilly-grade"><span>Open Brilly Finder</span><strong id="brilly-new"></strong></div></div><p class="brilly-change" id="brilly-change"></p><p class="brilly-small" id="brilly-game-awards"></p><a id="brilly-annotation-source" href="#sources">Read the chosen annotation</a><details><summary>Why this result?</summary><p id="brilly-reason"></p><p id="brilly-model"></p><p id="brilly-engine"></p></details></div></div><details class="brilly-all"><summary>Awarded, source-listed and diagnostic moves in this game</summary><div class="brilly-table-wrap"><table class="brilly-table"><thead><tr><th>Move</th><th>Published</th><th>Previous</th><th>New</th></tr></thead><tbody id="brilly-all-awards"></tbody></table></div><p class="brilly-small">“Not listed” means absent from our chosen annotation scope. It does not mean the move is bad or the award is wrong.</p></details></div><noscript><p>The complete static tables and before/after boards are below. No JavaScript is needed to read the findings.</p></noscript></section>
<section class="brilly-section" aria-labelledby="lessons-title"><h2 id="lessons-title">What we learned at the board.</h2><ul class="brilly-lessons">{notes}</ul></section>
<section class="brilly-section" aria-labelledby="all-title"><h2 id="all-title">Every published landmark.</h2><p>All fourteen targets, including misses. These diagrams and Fast results also work without the interactive viewer.</p>{''.join(sections)}</section>
<section class="brilly-section" aria-labelledby="methods-title"><h2 id="methods-title">A small study, with its cards on the table.</h2><p>We ran all 492 mainline plies from the published game scores through the actual Mobile Maia analysis and classification code, in all three modes: 1,503 baseline positions. Both classifiers received the same Stockfish 18 evaluations, then kept their normal bounded confirmation checks. The model, cutoff and app rules were unchanged.</p><p>These games were chosen because they are famous. Opera and Fischer were already development examples; model training membership was not audited. This is a selected comparison with published annotations, not a population accuracy estimate or a reproduction of Chess.com’s private classifier.</p><details class="brilly-method"><summary>Search limits, evidence and caveats</summary><ul><li>Fast: depth 12 / up to 500 ms. Balanced: depth 14 / up to 1,000 ms. Thorough: depth 16 / up to 1,500 ms.</li><li>One Stockfish 18 thread, 64 MiB hash, two principal lines. Fresh engine/session per game and mode. Each classifier kept the app’s six-search-unit confirmation budget.</li><li>The source registry and runner were committed before fresh engine collection. Source excerpts and finishing fragments define fourteen fixed landmarks, not exhaustive labels for every move.</li><li>Awarding !! to a source’s ! is a generous promotion, not agreement with that annotation. Unmarked moves are not automatically false positives.</li><li>This is a native host study. Android engine, latency, memory and lifecycle qualification remain separate.</li></ul><p><a href="https://github.com/Dash1971/mobile-maia-research/blob/__RESEARCH_COMMIT__/studies/famous-brilliants-2026-11-28/PLAN.md">Read the frozen plan</a> · <a href="https://github.com/Dash1971/mobile-maia-research/blob/__RESEARCH_COMMIT__/studies/famous-brilliants-2026-11-28/README.md">Data and reproduction</a> · <a href="games.pgn" download>Download the nine game scores</a></p></details></section>
<section class="brilly-section" id="sources" aria-labelledby="sources-title"><h2 id="sources-title">The annotators get a seat, too.</h2><p>Published ! and !! are human judgments. Our references include ChessBase, Chess.com staff and titled authors, US Chess, and GM Rafael Leitão. Exact sources, access limits and notation corrections are recorded in the research data.</p><ol class="brilly-source-list">{source_links}</ol><p class="brilly-figure-credit">Cburnett pieces by Colin M. L. Burnett · <a href="GPL-2.0.txt">GPL-2.0-or-later</a>. Boards show actual recorded positions. <a href="https://github.com/Dash1971/mobile-maia-research/blob/__RESEARCH_COMMIT__/studies/famous-brilliants-2026-11-28/THIRD_PARTY.md">Artwork and source notices</a>.</p><p><a href="https://github.com/Dash1971/mobile-maia-research/blob/__RESEARCH_COMMIT__/studies/famous-brilliants-2026-11-28/REPORT.md">Read the research-repository report</a> · <a href="https://github.com/Dash1971/maia-chess-android-preview/pull/284">Preview implementation</a></p></section>
</main>'''
    (ROOT / 'web/article-body.html').write_text(body + '\n')
    (ROOT / 'web/index-card.json').write_text(json.dumps({'title': 'Can a model spot a masterpiece?', 'description': editorial['card']}, ensure_ascii=False, indent=2) + '\n')
    imports = []
    mapping = {'web/article-body.html': 'research-source/brilliant-study/article-body.html', 'web/index-card.json': 'research-source/brilliant-study/index-card.json', **{f'web/{name}': f'site/research/brilliant-moves/{name}' for name in ['brilliant.css', 'brilliant.js', 'results.json']}, 'data/games.pgn': 'site/research/brilliant-moves/games.pgn', 'GPL-2.0.txt': 'site/research/brilliant-moves/GPL-2.0.txt'}
    for path in sorted((ROOT / 'figures').glob('*.png')): mapping[f'figures/{path.name}'] = f'site/research/brilliant-moves/figures/{path.name}'
    for path in sorted((ROOT / 'artwork').glob('*.webp')): mapping[f'artwork/{path.name}'] = f'site/research/brilliant-moves/artwork/{path.name}'
    for source, target in mapping.items():
        content = (ROOT / source).read_bytes()
        imports.append({'source': source, 'target': target, 'bytes': len(content), 'sha256': hashlib.sha256(content).hexdigest()})
    (ROOT / 'web/website-files.json').write_text(json.dumps({'files': imports}, indent=2) + '\n')
    print(f"Prepared {len(imports)} pinned website files, {sum(i['bytes'] for i in imports):,} bytes.")


if __name__ == '__main__':
    main()
